def check_m(m):
    import itertools
    # Total edges in K_m
    edges = list(itertools.combinations(range(m), 2))
    num_edges = len(edges)

    # Each edge must have a color from {0, 1, ..., m-1}
    # We want a coloring such that:
    # 1. Each color is used (m-1)/2 times
    # 2. Every triangle has 3 distinct colors
    # 3. Every triple of colors is used exactly once

    if (m-1) % 2 != 0:
        return False

    # Let's try the cyclic coloring: c(i, j) = (i + j) % m
    coloring = {}
    for i, j in edges:
        coloring[(i, j)] = (i + j) % m

    # Check 1: Each color is used (m-1)/2 times
    counts = {}
    for color in coloring.values():
        counts[color] = counts.get(color, 0) + 1

    if any(count != (m-1)//2 for count in counts.values()):
        return False
    if len(counts) != m:
        return False

    # Check 2: Every triangle has 3 distinct colors
    triangles = list(itertools.combinations(range(m), 3))
    for t in triangles:
        c1 = coloring[tuple(sorted((t[0], t[1])))]
        c2 = coloring[tuple(sorted((t[1], t[2])))]
        c3 = coloring[tuple(sorted((t[2], t[0])))]
        if len({c1, c2, c3}) != 3:
            return False

    # Check 3: Every triple of colors is used exactly once
    color_triples = set()
    for t in triangles:
        c1 = coloring[tuple(sorted((t[0], t[1])))]
        c2 = coloring[tuple(sorted((t[1], t[2])))]
        c3 = coloring[tuple(sorted((t[2], t[0])))]
        color_triples.add(tuple(sorted((c1, c2, c3))))

    if len(color_triples) == m * (m-1) * (m-2) // 6:
        return True
    return False

results = {}
for m in range(3, 51):
    results[m] = check_m(m)

print(results)

